def market():
    states={p['address']:Pool.from_json(p) for p in REAL['pools']}
    route=Route(tuple(REAL['route']['tokens']),tuple(REAL['route']['pools']))
    return route,states

def test_live_zero_prefix_route_finishes_sizing_without_masking_zero_input_errors():
    route,states=market();maximum,_=route_capacity(route,states)
    result=optimize(route,states,maximum)
    assert result['complete']
    assert route.quote(states,result['amount_in'])[0]==result['amount_out']
    assert result['gross_surplus']==result['amount_out']-result['amount_in']
    with pytest.raises(Reject,match='amount out of range'):
        next(p for p in states.values() if p.kind!='v2').quote(next(p for p in states.values() if p.kind!='v2').token0,0)

def test_zero_prefix_keeps_upstream_rounding_edges():
    # Buying a low-decimal token rounds to zero at this seed. A larger input
    # crosses a real V2 output edge, which must remain available to sizing.
    route,states=market();first=states[route.pools[0]]
    class ZeroV2:
        kind='v2';token0='a';token1='b';reserve0=10000;reserve1=5
        def quote(self,token,amount):return amount*997*5//(10000*1000+amount*997),0
    class NextLeg:
        kind='v3'
        def quote(self,token,amount):
            raise AssertionError('zero output must not be passed to downstream pool')
    r=Route(('a','b','a'),('first','second'))
    edges=v2_rounding_points(r,{'first':ZeroV2(),'second':NextLeg()},1,10000)
    assert 2508 in edges

def test_one_route_domain_error_does_not_erase_other_decisions(monkeypatch):
    route,states=market();config=load_config();config['policy']['max_quote_ms']=10000
    ix=RouteIndex(list(states.values()),[route.tokens[0]],4)
    assert len(ix.routes)>=2
    import searcher.engine as engine
    original=engine.marginal_profitable;calls=[]
    bad=next(iter(ix.routes))
    def reject_one(r,st):
        calls.append(r.key)
        if r.key==bad:raise Reject('invalid tick liquidity')
        return original(r,st)
    monkeypatch.setattr(engine,'marginal_profitable',reject_one)
    report=evaluate(ix,config,REAL['header'])
    assert report['rejected']['route_quote_rejected']==1
    assert report['route_errors']==[{'route_key':bad,'reason':'invalid tick liquidity'}]
    assert len(calls)>1 and report['routes_considered']==len(ix.routes)
    assert report['routes_deferred']==0
